"""Meridian CRM 4.2 CRMScript division semantics."""

from __future__ import annotations


def _coerce_numeric(value: object) -> float:
    """Apply legacy numeric-context coercion for supported operand values."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        # Defensive fallback: legacy numeric-context missing/empty values are zero.
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Perform legacy CRMScript division, preserving its divide-by-zero quirk."""
    numerator = _coerce_numeric(a)
    denominator = _coerce_numeric(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except Exception:
        # The legacy expression engine does not propagate division failures.
        return 0.0, []
